        with self.subTest(
            fixture="6_verified_root_exclusive_anchor_routing_healthy_and_stat_error"
        ):
            base_6 = (
                self.repo_root.parent
                / f"persist_verified_root_anchor_6_{pid}"
            )
            child_dir_6 = base_6 / "refmac"
            parent_dir_6 = base_6 / "refmac_parent_retention"
