                                    parent_retention_dir=parent_3,
                                    parent_retention_dir_baseline=parent_baseline_3,
                                    parent_dir_unusable_reason="owned fixture",
                                    verified_root_fallback_state=fb_state,
                                    caught_persistence_exceptions=causes_3,
